 public function setup(Request $r):array{[$sid,$m,$campuses]=$this->pay->context($r);$admin=$this->pay->finance($r)||$this->pay->can($r,'staff.manage')||$this->pay->can($r,'staff.attendance')||$this->pay->can($r,'staff.leave_approve');$staff=$admin?DB::table('staff_profiles as p')->join('school_memberships as m','m.id','=','p.membership_id')->join('users as u','u.id','=','m.user_id')->where('p.school_id',$sid)->where(function($q)use($sid,$campuses){$q->whereIn('p.id',DB::table('staff_employments')->where('school_id',$sid)->whereIn('campus_id',$campuses)->select('staff_profile_id'))->orWhereIn('p.membership_id',DB::table('membership_campuses')->where('school_id',$sid)->whereIn('campus_id',$campuses)->select('membership_id'));})->orderBy('u.name')->get(['p.*','u.name','u.email','m.status as membership_status']):collect();$jobs=DB::table('staff_employments')->where('school_id',$sid)->whereIn('staff_profile_id',$staff->pluck('id'))->whereIn('campus_id',$campuses)->orderByDesc('starts_on')->get();$members=$this->pay->can($r,'staff.manage')?DB::table('school_memberships as m')->join('users as u','u.id','=','m.user_id')->where('m.school_id',$sid)->where('m.status','active')->whereIn('m.id',DB::table('membership_campuses')->where('school_id',$sid)->whereIn('campus_id',$campuses)->select('membership_id'))->orderBy('u.name')->get(['m.id','u.name','u.email']):collect();$finance=$this->pay->finance($r);return ['today'=>$this->pay->today(),'campuses'=>DB::table('campuses')->where('school_id',$sid)->whereIn('id',$campuses)->orderBy('name')->get(['id','name','status']),'staff'=>$staff,'employments'=>$jobs,'members'=>$members,'can_staff_manage'=>$this->pay->can($r,'staff.manage'),'can_attendance'=>$this->pay->can($r,'staff.attendance'),'can_leave_approve'=>$this->pay->can($r,'staff.leave_approve'),'can_manage'=>$this->pay->can($r,'payroll.manage'),'can_approve'=>$this->pay->can($r,'payroll.approve'),'finance'=>$finance,'bank_accounts'=>$finance?DB::table('bank_accounts')->where('school_id',$sid)->where(fn($q)=>$q->whereNull('campus_id')->orWhereIn('campus_id',$campuses))->get(['id','name','campus_id']):collect()];}
 public function profile(Request $r,array $d,?int $id=null):array{return DB::transaction(function()use($r,$d,$id){$sid=$this->pay->lock($r,'staff.manage');if($id){$old=$this->pay->staff($r,$id,false,true);if($old->membership_id!=$d['membership_id'])$this->pay->fail('A staff profile stays linked to its original school account.');}else{$m=DB::table('school_memberships')->where('school_id',$sid)->where('id',$d['membership_id'])->where('status','active')->first()??abort(404);[,,$campuses]=$this->pay->context($r);abort_unless(DB::table('membership_campuses')->where('school_id',$sid)->where('membership_id',$m->id)->whereIn('campus_id',$campuses)->exists(),404);if(DB::table('staff_profiles')->where('school_id',$sid)->where('membership_id',$m->id)->exists())$this->pay->fail('This school user already has a staff profile.');}if(DB::table('staff_profiles')->where('school_id',$sid)->where('employee_no',$d['employee_no'])->when($id,fn($q)=>$q->where('id','<>',$id))->exists())$this->pay->fail('Employee number already exists.');if($id&&$d['status']==='inactive'&&DB::table('staff_employments')->where('school_id',$sid)->where('staff_profile_id',$id)->where(fn($q)=>$q->whereNull('ends_on')->orWhere('ends_on','>=',$this->pay->today()))->exists())$this->pay->fail('End current/future appointments before deactivating staff.');if($id&&!empty($d['hired_on'])&&DB::table('staff_employments')->where('school_id',$sid)->where('staff_profile_id',$id)->where('starts_on','<',$d['hired_on'])->exists())$this->pay->fail('Hire date cannot be later than an existing appointment.');$values=$d+['updated_at'=>now()];if($id)DB::table('staff_profiles')->where('school_id',$sid)->where('id',$id)->update($values);else $id=DB::table('staff_profiles')->insertGetId($values+['school_id'=>$sid,'created_at'=>now()]);$this->pay->access->audit($r,'staff.profile_saved','staff_profiles',$id,$d);return ['id'=>$id,'message'=>'Staff profile saved.'];});}
 public function employment(Request $r,array $d,?int $id=null):array{return DB::transaction(function()use($r,$d,$id){$sid=$this->pay->lock($r,'staff.manage');$p=$this->pay->staff($r,$d['staff_profile_id'],false,true);$this->pay->campus($r,$d['campus_id'],true);if($p->hired_on&&$d['starts_on']<$p->hired_on)$this->pay->fail('Appointment cannot start before the hire date.');if($p->status!=='active'||$p->membership_status!=='active')$this->pay->fail('Activate the staff profile and school membership first.');if(!DB::table('membership_campuses')->where('school_id',$sid)->where('membership_id',$p->membership_id)->where('campus_id',$d['campus_id'])->exists())$this->pay->fail('Assign this campus to the staff school account first.');$end=$d['ends_on']??'9999-12-31';$jobs=DB::table('staff_employments')->where('school_id',$sid)->where('staff_profile_id',$p->id)->when($id,fn($q)=>$q->where('id','<>',$id))->get();foreach($jobs as $job){if($job->starts_on<=$end&&($job->ends_on??'9999-12-31')>=$d['starts_on'])$this->pay->fail('Staff appointments must not overlap. End the earlier appointment first.');if($job->campus_id!=$d['campus_id']&&substr($job->starts_on,0,7)<=substr($end,0,7)&&substr($job->ends_on??'9999-12-31',0,7)>=substr($d['starts_on'],0,7))$this->pay->fail('Campus transfers must take effect in a different payroll month.');}
  if($id){$old=DB::table('staff_employments')->where('school_id',$sid)->where('id',$id)->first()??abort(404);$this->pay->campus($r,$old->campus_id);if($old->lock_version!=$d['lock_version']||$old->staff_profile_id!==$p->id||$old->campus_id!=$d['campus_id']||$old->starts_on!==$d['starts_on'])$this->pay->fail('Reload this appointment. Only its end date can be corrected.');$from=min($old->ends_on??'9999-12-31',$end);$latest=DB::table('payroll_items as i')->join('payroll_runs as r','r.id','=','i.payroll_run_id')->where('i.school_id',$sid)->where('i.staff_profile_id',$p->id)->where('r.status','approved')->max('r.period');if($latest&&CarbonImmutable::parse($latest)->endOfMonth()->toDateString()>$from)$this->pay->fail('This change would alter an approved payroll month. Use a reviewed payroll adjustment.');if(DB::table('staff_attendance_records')->where('school_id',$sid)->where('staff_profile_id',$p->id)->where('campus_id',$old->campus_id)->where('attendance_date','>=',$old->starts_on)->where('attendance_date','>',$end)->when($old->ends_on,fn($q)=>$q->where('attendance_date','<=',$old->ends_on))->exists())$this->pay->fail('Saved attendance exists after this end date; review it first.');DB::table('staff_employments')->where('school_id',$sid)->where('id',$id)->update(['ends_on'=>$d['ends_on']??null,'lock_version'=>$old->lock_version+1,'updated_at'=>now()]);}
  else{if(DB::table('payroll_items as i')->join('payroll_runs as r','r.id','=','i.payroll_run_id')->where('i.school_id',$sid)->where('i.staff_profile_id',$p->id)->where('r.status','approved')->where('r.period','>=',substr($d['starts_on'],0,7).'-01')->exists())$this->pay->fail('An approved payroll covers this history. Use a reviewed adjustment, not a backdated appointment.');$id=DB::table('staff_employments')->insertGetId(['school_id'=>$sid,'staff_profile_id'=>$p->id,'campus_id'=>$d['campus_id'],'starts_on'=>$d['starts_on'],'ends_on'=>$d['ends_on']??null,'created_at'=>now(),'updated_at'=>now()]);}$this->pay->access->audit($r,'staff.appointment_saved','staff_employments',$id,$d);return ['id'=>$id,'message'=>'Staff appointment saved.'];});}
 public function attendance(Request $r,int $campus,string $date):array{[$sid]=$this->pay->context($r,'staff.attendance');$this->pay->campus($r,$campus);if($date>$this->pay->today())$this->pay->fail('Staff attendance cannot be marked in the future.');$rows=DB::table('staff_employments as e')->join('staff_profiles as p','p.id','=','e.staff_profile_id')->join('school_memberships as m','m.id','=','p.membership_id')->join('users as u','u.id','=','m.user_id')->where('e.school_id',$sid)->where('e.campus_id',$campus)->where('e.starts_on','<=',$date)->where(fn($q)=>$q->whereNull('e.ends_on')->orWhere('e.ends_on','>=',$date))->orderBy('u.name')->get(['p.id as staff_profile_id','p.employee_no','p.designation','u.name']);if($rows->pluck('staff_profile_id')->unique()->count()!==$rows->count())$this->pay->fail('Overlapping appointments need review.');$saved=DB::table('staff_attendance_records')->where('school_id',$sid)->where('attendance_date',$date)->whereIn('staff_profile_id',$rows->pluck('staff_profile_id'))->get()->keyBy('staff_profile_id');$leaves=DB::table('leave_requests')->where('school_id',$sid)->whereIn('staff_profile_id',$rows->pluck('staff_profile_id'))->where('status','approved')->where('starts_on','<=',$date)->where('ends_on','>=',$date)->get()->keyBy('staff_profile_id');foreach($rows as $row){$record=$saved->get($row->staff_profile_id);$row->status=$record?->status;$row->arrived_at=$record?->arrived_at;$row->remarks=$record?->remarks;$row->leave_request_id=$record?->leave_request_id;$row->lock_version=(int)($record->lock_version??0);$row->approved_leave=$leaves->get($row->staff_profile_id);$row->campus_conflict=$record&&$record->campus_id!==$campus;}return ['date'=>$date,'campus_id'=>$campus,'rows'=>$rows];}
 public function saveAttendance(Request $r,array $d):array{return DB::transaction(function()use($r,$d){$sid=$this->pay->lock($r,'staff.attendance');$this->pay->campus($r,$d['campus_id'],true);$day=$this->attendance($r,$d['campus_id'],$d['date']);$map=$day['rows']->keyBy('staff_profile_id');foreach($d['records'] as $row){$staff=$map->get($row['staff_profile_id'])??abort(404);if($staff->campus_conflict)$this->pay->fail('This employee already has attendance in another campus on this date.');if($staff->lock_version!=$row['lock_version'])$this->pay->fail('A newer staff attendance change exists. Reload before saving.');if($row['status']==='leave'){if(!$staff->approved_leave||$staff->approved_leave->id!=($row['leave_request_id']??null))$this->pay->fail('Leave marking requires the approved leave request covering this date.');}elseif($staff->approved_leave)$this->pay->fail('An approved leave covers this date. Cancel/review it before marking another status.');if(!in_array($row['status'],['present','late'],true)&&!empty($row['arrived_at']))$this->pay->fail('Arrival time applies only to present or late staff.');$old=DB::table('staff_attendance_records')->where('school_id',$sid)->where('staff_profile_id',$staff->staff_profile_id)->where('attendance_date',$d['date'])->first();$values=['status'=>$row['status'],'arrived_at'=>!empty($row['arrived_at'])?$row['arrived_at']:null,'leave_request_id'=>$row['status']==='leave'?$row['leave_request_id']:null,'remarks'=>(trim($row['remarks']??'')===''?null:trim($row['remarks']))];$changed=!$old||$old->status!==$values['status']||substr($old->arrived_at??'',0,5)!==substr($values['arrived_at']??'',0,5)||$old->leave_request_id!=$values['leave_request_id']||$old->remarks!==$values['remarks'];if(!$changed)continue;if($old&&mb_strlen(trim($d['reason']??''))<5)$this->pay->fail('Attendance corrections need a reason of at least five characters.');$key=['school_id'=>$sid,'staff_profile_id'=>$staff->staff_profile_id,'attendance_date'=>$d['date']];DB::table('staff_attendance_records')->updateOrInsert($key,$values+['campus_id'=>$d['campus_id'],'recorded_by'=>$this->pay->access->membership($r)->id,'lock_version'=>$staff->lock_version+1,'updated_at'=>now()]);$id=DB::table('staff_attendance_records')->where($key)->value('id');$this->pay->access->audit($r,'staff.attendance_saved','staff_attendance_records',$id,['reason'=>$d['reason']??null,'before'=>$old,'after'=>$values]);}return ['message'=>'Staff attendance saved.'];});}
 public function leaveScope(Request $r,object $leave):object{$p=$this->pay->staff($r,$leave->staff_profile_id,true);[$sid,$m,$campuses]=$this->pay->context($r);if($p->membership_id===$m->id)return $p;$jobs=DB::table('staff_employments')->where('school_id',$sid)->where('staff_profile_id',$p->id)->where('starts_on','<=',$leave->ends_on)->where(fn($q)=>$q->whereNull('ends_on')->orWhere('ends_on','>=',$leave->starts_on))->get();abort_unless($jobs->count()&&$jobs->every(fn($j)=>in_array((int)$j->campus_id,$campuses,true)),404);return $p;}
 public function leaves(Request $r,bool $self=false){[$sid,$m,$campuses]=$this->pay->context($r);if(!$self)abort_unless($this->pay->can($r,'staff.leave_approve')||$this->pay->can($r,'staff.manage'),403);$q=DB::table('leave_requests as l')->join('staff_profiles as p','p.id','=','l.staff_profile_id')->join('school_memberships as m','m.id','=','p.membership_id')->join('users as u','u.id','=','m.user_id')->where('l.school_id',$sid);if($self)$q->where('p.membership_id',$m->id);else $q->whereExists(function($q)use($sid,$campuses){$q->selectRaw('1')->from('staff_employments as e')->where('e.school_id',$sid)->whereColumn('e.staff_profile_id','l.staff_profile_id')->whereIn('e.campus_id',$campuses)->whereColumn('e.starts_on','<=','l.ends_on')->where(fn($q)=>$q->whereNull('e.ends_on')->orWhereColumn('e.ends_on','>=','l.starts_on'));})->whereNotExists(function($q)use($sid,$campuses){$q->selectRaw('1')->from('staff_employments as e')->where('e.school_id',$sid)->whereColumn('e.staff_profile_id','l.staff_profile_id')->whereNotIn('e.campus_id',$campuses)->whereColumn('e.starts_on','<=','l.ends_on')->where(fn($q)=>$q->whereNull('e.ends_on')->orWhereColumn('e.ends_on','>=','l.starts_on'));});return $q->orderByDesc('l.id')->paginate(20,['l.*','p.employee_no','u.name']);}
 public function requestLeave(Request $r,array $d):array{return DB::transaction(function()use($r,$d){$sid=$this->pay->lock($r);$p=$this->pay->staff($r,$d['staff_profile_id'],true);[, $m]=$this->pay->context($r);abort_unless($p->membership_id===$m->id&&$this->pay->can($r,'staff.self')||$this->pay->can($r,'staff.manage'),403);$this->leaveScope($r,(object)$d);if(CarbonImmutable::parse($d['starts_on'])->diffInDays(CarbonImmutable::parse($d['ends_on']))>366)$this->pay->fail('Request at most one year of leave at a time.');for($date=CarbonImmutable::parse($d['starts_on']);$date->toDateString()<=$d['ends_on'];$date=$date->addDay())if(!DB::table('staff_employments')->where('school_id',$sid)->where('staff_profile_id',$p->id)->where('starts_on','<=',$date->toDateString())->where(fn($q)=>$q->whereNull('ends_on')->orWhere('ends_on','>=',$date->toDateString()))->exists())$this->pay->fail('Appointments must cover the entire leave range.');if(DB::table('leave_requests')->where('school_id',$sid)->where('staff_profile_id',$p->id)->whereIn('status',['pending','approved'])->where('starts_on','<=',$d['ends_on'])->where('ends_on','>=',$d['starts_on'])->exists())$this->pay->fail('Another pending or approved leave overlaps these dates.');$id=DB::table('leave_requests')->insertGetId($d+['school_id'=>$sid,'status'=>'pending','created_at'=>now(),'updated_at'=>now()]);$this->pay->access->audit($r,'staff.leave_requested','leave_requests',$id,$d);return ['message'=>'Leave requested.','id'=>$id];});}
 public function reviewLeave(Request $r,int $id,array $d):array{return DB::transaction(function()use($r,$id,$d){$sid=$this->pay->lock($r);$leave=DB::table('leave_requests')->where('school_id',$sid)->where('id',$id)->first()??abort(404);$p=$this->leaveScope($r,$leave);[, $m]=$this->pay->context($r);$owner=in_array('owner',$this->pay->access->roles($m),true);if($leave->lock_version!=$d['lock_version'])$this->pay->fail('Leave changed. Reload before reviewing.');if($d['action']==='cancel'){abort_unless(($leave->status==='pending'&&$p->membership_id===$m->id)||$this->pay->can($r,'staff.leave_approve'),403);if(!in_array($leave->status,['pending','approved'],true))$this->pay->fail('Only pending or approved leave can be cancelled.');$status='cancelled';}else{abort_unless($this->pay->can($r,'staff.leave_approve'),403);if(!$owner&&$p->membership_id===$m->id)$this->pay->fail('Another approver must review your own leave request.');if($leave->status!=='pending')$this->pay->fail('Only pending leave can be approved/rejected.');$status=$d['action']==='approve'?'approved':'rejected';}DB::table('leave_requests')->where('school_id',$sid)->where('id',$id)->update(['status'=>$status,'approved_by'=>$m->id,'review_note'=>$d['reason'],'reviewed_at'=>now(),'lock_version'=>$leave->lock_version+1,'updated_at'=>now()]);$this->pay->access->audit($r,'staff.leave_'.$status,'leave_requests',$id,['reason'=>$d['reason'],'before'=>$leave->status]);return ['message'=>'Leave '.$status.'.'];});}
